INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(41161, 'Isaiah 32:3', 'Isaiah', 32, 3, 'نو بیا به د هغوی سترګې د حقیقت د لیدلو دپاره بندې نه وي او غوږونه به یې د اورېدلو دپاره خلاص وي.', 'نو بیا به د هغوی سترګې د حقیقت د لیدلو دپاره بندې نه وی او غوزونه به یې د اورېدلو دپاره خلاص وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_003.mp3', 'https://drive.google.com/file/d/1VduVYeWFMbwGqGDU_81r7BKov0YCUMtK/preview', 1761237841, 1761237841),
(41162, 'Isaiah 32:4', 'Isaiah', 32, 4, 'هغوی به نور نه بې حوصلې کیږي، بلکې په هوښیارۍ سره به عمل کوي. د چا چې ژبه بندیږي هغوی به د خلکو سره په روانه ژبه خبرې وکړي.', 'هغوی به نور نه بې حوصلې کیزی، بلکې په هوشیاری سره به عمل کوی. د چا چې ژبه بندیزی هغوی به د خلکو سره په روانه ژبه خبرې وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_004.mp3', 'https://drive.google.com/uc?id=1kyAZximtUhv94HG3Gmbf_LCpYUibMp7E&export=download', 1761237841, 1761237841),
(41163, 'Isaiah 32:5', 'Isaiah', 32, 5, 'نور به هېڅوک بې عقله سړي ته شریف او رذیل سړي ته نېک ونه وایي.', 'نور به هېچوک بې عقله سری ته شریف او رذیل سری ته نېک ونه وایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_005.mp3', 'https://drive.google.com/file/d/1bcxJUGH4LbJVP2IpqmY0hE95qZiiCii8/preview', 1761237841, 1761237841),
(41164, 'Isaiah 32:6', 'Isaiah', 32, 6, 'بې عقله سړی بې عقلې خبرې کوي او د بدو کارونو په اړه فکر کوي. هغه غواړي چې بد کارونه او د څښتن په خلاف غلطې ویناوې وکړي. له وږو خلکو سره مرسته نه کوي او تږو خلکو ته اوبه نه ورکوي.', 'بې عقله سری بې عقلې خبرې کوی او د بدو کارونو په اره فکر کوی. هغه غواری چې بد کارونه او د چشتن په خلاف غلطې ویناوې وکری. له وزو خلکو سره مرسته نه کوی او تزو خلکو ته اوبه نه ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_006.mp3', 'https://drive.google.com/uc?id=1Bu4MahLJY-9RxAZXWJsOQdexDwEi30Mq&export=download', 1761237841, 1761237841),
(41165, 'Isaiah 32:7', 'Isaiah', 32, 7, 'رذیل سړی بد سړی وي او بد کارونه کوي. هغه د دروغو په ویلو سره د غریبانو د تباه کولو دپاره دسیسې جوړوي او د دې مخه نیسي چې هغوی دې خپل حقونه تر لاسه کړي.', 'رذیل سری بد سری وی او بد کارونه کوی. هغه د دروغو په ویلو سره د غریبانو د تباه کولو دپاره دسیسې جوروی او د دې مخه نیسی چې هغوی دې خپل حقونه تر لاسه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_007.mp3', 'https://drive.google.com/uc?id=1QLfn-lMRJihX76yQtr2xlwvtZG63HCck&export=download', 1761237841, 1761237841),
(41166, 'Isaiah 32:8', 'Isaiah', 32, 8, 'خو شریف خلک د نېک کار نقشه جوړوي او په نېک کار باندې ټینګ ولاړ وي.', 'خو شریف خلک د نېک کار نقشه جوروی او په نېک کار باندې تینګ ولار وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_008.mp3', 'https://drive.google.com/uc?id=1lRaqeYfEEQPt__sUL2gg0NAIXSBxOYH2&export=download', 1761237841, 1761237841),
(41167, 'Isaiah 32:9', 'Isaiah', 32, 9, 'ای بې پروا ښځو، چې هوسا ژوند لرئ، زما خبرو ته غوږ ونیسئ. ای مېرمنو، چې په ځان باندې تکیه کوئ زما وینا ته پام وکړئ!', 'ای بې پروا شجو، چې هوسا ژوند لری، زما خبرو ته غوز ونیسی. ای مېرمنو، چې په جان باندې تکیه کوی زما وینا ته پام وکری!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_009.mp3', 'https://drive.google.com/file/d/1i0ozoag7lHezK3-QPczah2hTKlLhTGrt/preview', 1761237841, 1761237841),
(41168, 'Isaiah 32:10', 'Isaiah', 32, 10, 'اوس تاسو د خپل ژوند څخه راضي یئ، خو یو کال او څو ورځې وروسته به تاسو په لړزېدلو شئ، ځکه د انګورو او د نورو مېوو حاصلات به نه وي چې هغه راټول کړئ.', 'اوس تاسو د خپل ژوند چخه راضی یی، خو یو کال او چو ورجې وروسته به تاسو په لرزېدلو شی، جکه د انګورو او د نورو مېوو حاصلات به نه وی چې هغه راتول کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_010.mp3', 'https://drive.google.com/file/d/1LRUGZSwmdkaKDPDnaDPJj0LjyAl1C3a5/preview', 1761237841, 1761237841),
(41169, 'Isaiah 32:11', 'Isaiah', 32, 11, 'ای ښځو، تاسو چې ارام او بې غمه ژوند لرئ، اوس له وېرې په لړزېدلو شئ! خپل کالي وباسئ، بربنډې شئ او د ویر کالي واغوندئ.', 'ای شجو، تاسو چې ارام او بې غمه ژوند لری، اوس له وېرې په لرزېدلو شی! خپل کالی وباسی، بربندې شی او د ویر کالی واغوندی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_011.mp3', 'https://drive.google.com/uc?id=1uu1CA8GNh3IjHAMidHacH-BVMcPhdm2E&export=download', 1761237841, 1761237841),
(41170, 'Isaiah 32:12', 'Isaiah', 32, 12, 'له غمه خپلې سینې ووهئ، ځکه چې حاصلخېزه پټي او د انګورو تاکونه مو تباه شوي دي', 'له غمه خپلې سینې ووهی، جکه چې حاصلخېزه پتی او د انګورو تاکونه مو تباه شوی دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_012.mp3', 'https://drive.google.com/uc?id=1lT69IbKWv-ZrtkMAGUurwqfcNaZMIXs8&export=download', 1761237841, 1761237841),
(41171, 'Isaiah 32:13', 'Isaiah', 32, 13, 'او د اغزیو او د کرکڼو بوټي زما د قوم په ځمکه کې راشنه شوي دي. هو، په دې خاطر هم غم وکړئ چې د هغو د کورونو او د ښار خوشحالي او خندا به پای ته ورسیږي.', 'او د اغزیو او د کرکنو بوتی زما د قوم په جمکه کې راشنه شوی دی. هو، په دې خاطر هم غم وکری چې د هغو د کورونو او د شار خوشحالی او خندا به پای ته ورسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_013.mp3', 'https://drive.google.com/uc?id=14EdTC8yfAZ1b4wwGrWqeZyu4UmDBi8-I&export=download', 1761237841, 1761237841),
(41172, 'Isaiah 32:14', 'Isaiah', 32, 14, 'حتی پاچا به هم شاهي ماڼۍ پرېږدي او له ګڼه ګوڼې ډک پایتخت به له خلکو څخه بیخي خالي شي. هغه جنګي کلا او د هغه برجونه چې د هغو په وسیله به څارنه کېدله، هغه به وران او د تل دپاره به د حیواناتو استوګن ځای شي. ځنګلي خره به په کې هسې ګرځي او راګرځي او پسونه به په کې څریږي.', 'حتی پاچا به هم شاهی مانی پرېزدی او له ګنه ګونې دک پایتخت به له خلکو چخه بیخی خالی شی. هغه جنګی کلا او د هغه برجونه چې د هغو په وسیله به چارنه کېدله، هغه به وران او د تل دپاره به د حیواناتو استوګن جای شی. جنګلی خره به په کې هسې ګرجی او راګرجی او پسونه به په کې چریزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_014.mp3', 'https://drive.google.com/uc?id=15HyMIRgaULT4-3ga67nO1NofhHO1RvmQ&export=download', 1761237841, 1761237841),
(41173, 'Isaiah 32:15', 'Isaiah', 32, 15, 'تر هغه وخته به حالات همداسې وي، ترڅو چې د اسمان څخه په مونږ باندې د خدای روح نازل شي. دښته به په حاصلخیزه پټي بدله شي او دا پټی به ډېر حاصلخېزه وي.', 'تر هغه وخته به حالات همداسې وی، ترچو چې د اسمان چخه په مونز باندې د خدای روح نازل شی. دشته به په حاصلخیزه پتی بدله شی او دا پتی به دېر حاصلخېزه وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_015.mp3', 'https://drive.google.com/uc?id=1Yqk7WBuNq-o-UYxJ2QYJPwJHABTq38Ud&export=download', 1761237841, 1761237841),
(41174, 'Isaiah 32:16', 'Isaiah', 32, 16, 'نو بیا به عدالت په دښته کې پیاده شي او انصاف به په حاصلخیزه پټي کې عملي شي.', 'نو بیا به عدالت په دشته کې پیاده شی او انصاف به په حاصلخیزه پتی کې عملی شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_016.mp3', 'https://drive.google.com/file/d/1MUYjGh2hFEReZNV4_z0pCk4pbn0MZCN8/preview', 1761237841, 1761237841),
(41175, 'Isaiah 32:17', 'Isaiah', 32, 17, 'د انصاف نتیجه به تلپاتې سوله او امن وي.', 'د انصاف نتیجه به تلپاتې سوله او امن وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_017.mp3', 'https://drive.google.com/file/d/1DB2QKsRukK3_LBkVSn8De-YzEA6rcLLm/preview', 1761237841, 1761237841),
(41176, 'Isaiah 32:18', 'Isaiah', 32, 18, 'زما قوم به په امن ځایونو کې اوسیږي او کورونه به یې خوندي او ارام وي.', 'زما قوم به په امن جایونو کې اوسیزی او کورونه به یې خوندی او ارام وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_018.mp3', 'https://drive.google.com/file/d/1VBQt-3DeMtz8TxEXcCgSp2qLfluwoYnr/preview', 1761237841, 1761237841),
(41177, 'Isaiah 32:19', 'Isaiah', 32, 19, 'حتی که ږلۍ ځنګلونه ویجاړ هم کړي او ښارونه د خاورو سره خاورې هم شي.', 'حتی که زلی جنګلونه ویجار هم کری او شارونه د خاورو سره خاورې هم شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_019.mp3', 'https://drive.google.com/uc?id=1Y39lN7g9KbeKZG9vTCrTFKAc8XobJoQX&export=download', 1761237841, 1761237841),
(41178, 'Isaiah 32:20', 'Isaiah', 32, 20, 'بختور یئ تاسو چې د کروندو دپاره پرېمانه اوبه لرئ او د خرو او غویانو دپاره هر چېرته د څرېدلو ځایونه لرئ.', 'بختور یی تاسو چې د کروندو دپاره پرېمانه اوبه لری او د خرو او غویانو دپاره هر چېرته د چرېدلو جایونه لری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah032_verse_020.mp3', 'https://drive.google.com/uc?id=1ELuT9vynDcywLoSML8LFrReKO0jumtvp&export=download', 1761237841, 1761237841),
(41179, 'Job 4:1', 'Job', 4, 1, 'بيا تيمانى اليفز په جواب کښې ووئيل،', 'بیا تیمانی الیفز په جواب کشې ووییل،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41180, 'Job 4:2', 'Job', 4, 2, '”کۀ څوک تا ته يوه خبره وکړى نو تۀ به خفه کېږې څۀ؟ خو د خبرو نه څوک ځان منع کولے شى؟', '”کۀ چوک تا ته یوه خبره وکری نو تۀ به خفه کېزې چۀ؟ خو د خبرو نه چوک جان منع کولے شی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41181, 'Job 4:3', 'Job', 4, 3, 'ګوره، تا ډېرو خلقو ته ښودنه کړې ده، تا کمزورى لاسونه تکړه کړى دى.', 'ګوره، تا دېرو خلقو ته شودنه کرې ده، تا کمزوری لاسونه تکره کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41182, 'Job 4:4', 'Job', 4, 4, 'ستا ډاډګيرنې خلق په خپلو پښو ودرولى دى. کوم خلق چې په غورزېدو وُو هغوئ يې نېغ کړى دى.', 'ستا دادګیرنې خلق په خپلو پشو ودرولی دی. کوم خلق چې په غورزېدو وو هغوی یې نېغ کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41183, 'Job 4:5', 'Job', 4, 5, 'خو اوس مصيبت په تا باندې راغلے دے او تۀ وارخطا يې، چې دا تا له درنزدې شى نو تۀ پرېشانه شې.', 'خو اوس مصیبت په تا باندې راغلے دے او تۀ وارخطا یې، چې دا تا له درنزدې شی نو تۀ پرېشانه شې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41184, 'Job 4:6', 'Job', 4, 6, 'ستا اعتماد د خُدائ پاک يره نۀ ده څۀ، او ستا نېک عمل تا له اُميد نۀ درکوى؟', 'ستا اعتماد د خدای پاک یره نۀ ده چۀ، او ستا نېک عمل تا له امید نۀ درکوی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41185, 'Job 4:7', 'Job', 4, 7, 'اوس دا سوچ وکړه، داسې څوک شته چې بې‌ګناه وى او تباه شى؟ او داسې څوک صادق شته چې تباه شوے وى؟', 'اوس دا سوچ وکره، داسې چوک شته چې بې‌ګناه وی او تباه شی؟ او داسې چوک صادق شته چې تباه شوے وی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41186, 'Job 4:8', 'Job', 4, 8, 'چې څومره ما ته پته ده، چې چا دا بې‌اِنصافى کړې ده چې چا مصيبت کَرلے دے، نو هغۀ مصيبت رېبلے دے.', 'چې چومره ما ته پته ده، چې چا دا بې‌انصافی کرې ده چې چا مصیبت کرلے دے، نو هغۀ مصیبت رېبلے دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237841, 1761237841),
(41187, 'Job 4:9', 'Job', 4, 9, 'د خُدائ پاک د ساه په ذريعه هغوئ سزا موندلې ده، او د هغۀ د غصې د زور په وجه هغوئ تباه شوى دى.', 'د خدای پاک د ساه په ذریعه هغوی سزا موندلې ده، او د هغۀ د غصې د زور په وجه هغوی تباه شوی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41188, 'Job 4:10', 'Job', 4, 10, 'بدعمله د ازمرى په شان غړمبيږى، خو خُدائ پاک هغوئ غلى کوى او غاښونه يې ماتوى.', 'بدعمله د ازمری په شان غرمبیزی، خو خدای پاک هغوی غلی کوی او غاشونه یې ماتوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41189, 'Job 4:11', 'Job', 4, 11, 'لکه چې تکړه ازمرے د ښکار د کمى په وجه هلاکيږى، او د دې واړۀ بچى خوارۀ وارۀ شى.', 'لکه چې تکره ازمرے د شکار د کمی په وجه هلاکیزی، او د دې وارۀ بچی خوارۀ وارۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
(41190, 'Job 4:12', 'Job', 4, 12, 'اوس ما ته پټ پټ يو خبر راغلو، او زما غوږُونو ته د دې غلے شان آواز راغلو.', 'اوس ما ته پت پت یو خبر راغلو، او زما غوزونو ته د دې غلے شان اواز راغلو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_4_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237841, 1761237841),
